const KN_spark=(x,y,col)=>`<polyline points="${x-6},${y-22} ${x+8},${y-4} ${x-6},${y+2} ${x+6},${y+22}" fill="none" stroke="${col||ORG}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/>`;
const KN_therm=(x,y,col)=>`<rect x="${x-10}" y="${y-70}" width="20" height="74" rx="10" fill="#FFFFFF" stroke="${KN_STEEL}" stroke-width="3"/><rect x="${x-5}" y="${y-56}" width="10" height="60" rx="5" fill="${col}"/><circle cx="${x}" cy="${y+12}" r="16" fill="${col}" stroke="${KN_STEEL}" stroke-width="3"/>`;
/* a crank-angle scale: x0 at deg0, px per degree, with TDC marked */
const KN_scale=(x0,x1,y,d0,d1,ticks)=>{const k=(x1-x0)/(d1-d0),X=d=>x0+(d-d0)*k;let s=KN_L(x0,y,x1,y,'#343A40',4);
 ticks.forEach(d=>{s+=KN_L(X(d),y-10,X(d),y+10,'#343A40',3)+KN_T(X(d),y+40,d===0?'TDC':(Math.abs(d)+'°'),{fs:22,fw:d===0?800:600,a:'middle',fill:d===0?'#18213A':KN_GREY})});return s};
/* the end-gas chamber seen from above: plug at the left, burnt zone round it, end gas at the far side */
const KN_chamber=(u,cx,cy,R,rb,re,eg)=>{const px=cx-R,id='knch'+u+cx;return `<defs><clipPath id="${id}"><circle cx="${cx}" cy="${cy}" r="${R}"/></clipPath></defs>
 <circle cx="${cx}" cy="${cy}" r="${R}" fill="#F1F3F5"/>
 <g clip-path="url(#${id})"><circle cx="${px}" cy="${cy}" r="${rb}" fill="${ORG}" fill-opacity=".32"/><circle cx="${px}" cy="${cy}" r="${rb}" fill="none" stroke="${ORG}" stroke-width="5"/>
 <path d="M${px-R*3},${cy-R*3} h${R*6} v${R*6} h${-R*6} z M${px-re},${cy} a${re},${re} 0 1,0 ${2*re},0 a${re},${re} 0 1,0 ${-2*re},0" fill="${eg||'#CED4DA'}" fill-rule="evenodd"/></g>
 <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#343A40" stroke-width="5"/>
 <rect x="${px-30}" y="${cy-9}" width="34" height="18" rx="4" fill="${KN_STEEL}"/>${KN_spark(px+16,cy,'#F08C00')}`};

/* only the end-gas region of KN_chamber, for colouring it on a cue */
const KN_endgas=(u,cx,cy,R,re,col,op)=>{const px=cx-R,id='kneg'+u+cx;return `<defs><clipPath id="${id}"><circle cx="${cx}" cy="${cy}" r="${R}"/></clipPath></defs><g clip-path="url(#${id})"><path d="M${px-R*3},${cy-R*3} h${R*6} v${R*6} h${-R*6} z M${px-re},${cy} a${re},${re} 0 1,0 ${2*re},0 a${re},${re} 0 1,0 ${-2*re},0" fill="${col}" fill-opacity="${op}" fill-rule="evenodd"/></g><circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#343A40" stroke-width="5"/>`};

