function EXTRA(R,ICON){
 /* hook: the knocking petrol car on a hot hill, and the cold diesel at start-up */
 ICON.knHill=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${KN_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  <polygon points="14,150 366,150 366,64" fill="#E9ECEF"/><circle cx="330" cy="34" r="18" fill="#FFD43B"/>
  <g transform="rotate(-14 170 112)"><rect x="110" y="88" width="130" height="34" rx="10" fill="${ORG}"/><path d="M132,88 L150,66 L206,66 L222,88 Z" fill="${ORG}"/><rect x="156" y="72" width="40" height="14" rx="3" fill="#FFFFFF"/><circle cx="138" cy="124" r="13" fill="#343A40"/><circle cx="214" cy="124" r="13" fill="#343A40"/></g>
  ${KN_T(20,40,'knock!',{fs:28,fw:900,fill:RED})}${KN_T(116,38,'top gear, uphill',{fs:22,fw:700,fill:KN_GREY})}</g>`;
 ICON.knCold=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${KN_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  <rect x="24" y="44" width="150" height="96" rx="10" fill="${KN_IRON}" stroke="${KN_STEEL}" stroke-width="3"/><rect x="40" y="26" width="118" height="20" rx="5" fill="${KN_STEEL}"/>
  ${[0,1,2].map(i=>`<rect x="${44+i*42}" y="60" width="26" height="62" rx="4" fill="${KN_AL}"/>`).join('')}
  <g stroke="${BLU}" stroke-width="4" stroke-linecap="round">${[0,60,120].map(a=>`<line x1="${310+30*Math.cos(a*Math.PI/180)}" y1="${46+30*Math.sin(a*Math.PI/180)}" x2="${310-30*Math.cos(a*Math.PI/180)}" y2="${46-30*Math.sin(a*Math.PI/180)}"/>`).join('')}</g>
  <path d="M186,60 l16,10 M186,92 l20,0 M186,124 l16,-10" stroke="${RED}" stroke-width="4" stroke-linecap="round"/>
  ${KN_T(214,104,'clatter!',{fs:28,fw:900,fill:RED})}${KN_T(214,136,'cold diesel',{fs:22,fw:700,fill:KN_GREY})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.knGroups=(x,y)=>`<g transform="translate(${x-210} ${y-165})">
  ${KN_box(0,20,130,250,{fill:'#E7F5FF',st:BLU,sw:3})}${KN_therm(65,170,RED)}${KN_T(65,240,'density',{fs:24,fw:800,a:'middle',fill:BLU})}
  ${KN_box(145,20,130,250,{fill:'#FFF4E6',st:ORG,sw:3})}<circle cx="210" cy="130" r="42" fill="#FFFFFF" stroke="#343A40" stroke-width="5"/><rect x="202" y="76" width="16" height="12" fill="#343A40"/>${KN_L(210,130,210,100,'#343A40',4)}${KN_L(210,130,232,142,ORG,4)}${KN_T(210,240,'time',{fs:24,fw:800,a:'middle',fill:ORG})}
  ${KN_box(290,20,130,250,{fill:'#EBFBEE',st:GRN,sw:3})}<path d="M355,80 C385,124 390,150 355,176 C320,150 325,124 355,80 Z" fill="${GRN}"/>${KN_T(355,214,'fuel and',{fs:22,fw:800,a:'middle',fill:GRN})}${KN_T(355,244,'mixture',{fs:22,fw:800,a:'middle',fill:GRN})}
  ${KN_T(210,316,'all three decide knock',{fs:24,fw:800,a:'middle'})}</g>`;
 ICON.knStages=(x,y)=>{ /* the book's own heat-release points, scaled into the card */
  const P2=KN_CURVE.split(' ').map(p=>p.split(',').map(Number)),X=v=>20+(v-80)*380/610,Y=v=>290-(400-v)*250/300;
  const band=(a,b2,col,n)=>`<rect x="${X(a)}" y="20" width="${X(b2)-X(a)}" height="270" fill="${col}" fill-opacity=".22"/>`+`<circle cx="${(X(a)+X(b2))/2}" cy="44" r="17" fill="${col}"/>`+KN_T((X(a)+X(b2))/2,52,n,{fs:22,fw:800,a:'middle',fill:'#FFFFFF'});
  return `<g transform="translate(${x-210} ${y-165})">${band(118.1,200.5,BLU,'1')}${band(200.5,259.2,ORG,'2')}${band(259.2,461.2,GRN,'3')}${band(461.2,690,KN_GREY,'4')}
  <polyline points="${P2.map(([a,b2])=>X(a).toFixed(1)+','+Y(b2).toFixed(1)).join(' ')}" fill="none" stroke="#18213A" stroke-width="4" stroke-linejoin="round"/>
  ${KN_L(20,290,400,290,'#343A40',3)}${KN_T(210,326,'1 delay · 2 premixed · 3 mixing · 4 late',{fs:22,fw:800,a:'middle'})}</g>`};
 ICON.knDial=(x,y)=>{const cx=210,cy=170,r=130,pt=(d,rr)=>[cx+rr*Math.sin(d*Math.PI/180),cy-rr*Math.cos(d*Math.PI/180)],[ax,ay]=pt(-15,r),[bx,by]=pt(-4.2,r),[ax2,ay2]=pt(-15,r+26),[bx2,by2]=pt(-4.2,r+26);
  return `<g transform="translate(${x-210} ${y-165})"><circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="#343A40" stroke-width="5"/>
  <path d="M${cx},${cy} L${ax.toFixed(1)},${ay.toFixed(1)} A${r},${r} 0 0 1 ${bx.toFixed(1)},${by.toFixed(1)} Z" fill="${GRN}" fill-opacity=".6"/>
  ${KN_L(cx,cy-r-8,cx,cy-r+18,'#343A40',4)}${KN_T(cx+36,cy-r-6,'TDC',{fs:22,fw:800})}
  ${KN_T(ax2-6,ay2,'A',{fs:24,fw:800,a:'end',fill:BLU})}${KN_T(bx2+4,by2-4,'B',{fs:24,fw:800,a:'middle',fill:ORG})}
  ${KN_T(cx,cy+20,'10.8°',{fs:40,fw:900,a:'middle',fill:GRN})}${KN_T(cx,cy+60,'= 12 °/ms × 0.9 ms',{fs:22,fw:700,a:'middle',fill:KN_GREY})}</g>`};
}
